// Reporter output reuses the console's JSON quoting; no extra serializer/backend.
fn tsrust_testing_json()->bool{std::env::var("TSRUST_TEST_REPORTER").as_deref()==Ok("json")}
fn tsrust_testing_event(event:&str,name:&str,status:&str,messages:&[std::string::String],duration:std::time::Duration){let messages=messages.iter().map(|value|tsr_console_quote(value,true)).collect::<Vec<_>>().join(",");println!("{{\"event\":{},\"name\":{},\"status\":{},\"messages\":[{}],\"durationMs\":{}}}",tsr_console_quote(event,true),tsr_console_quote(name,true),tsr_console_quote(status,true),messages,duration.as_secs_f64()*1000.0);}
fn tsrust_testing_selected(name:&str)->bool{std::env::var("TSRUST_TEST_FILTER").ok().is_none_or(|filter|name.contains(&filter))}
fn tsrust_testing_test_counts(registry:&TsrTestRegistry)->(i64,i64){let mut total=0;let mut selected=0;let mut work=vec![(0,Vec::<std::string::String>::new())];while let Some((id,mut path))=work.pop(){if registry.suites[id].displayed{path.push(registry.suites[id].name.clone());}for entry in &registry.suites[id].entries{match entry{TsrTestEntry::Test{name,..}=>{total+=1;let mut name_path=path.clone();name_path.push(name.clone());selected+=i64::from(tsrust_testing_selected(&name_path.join(" > ")));},TsrTestEntry::Suite(child)=>work.push((*child,path.clone()))}}}(total,selected)}
thread_local!{static TSR_TEST_BODY:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};}
fn tsrust_testing_invoke_body(callback:&mut TsrTestCallback,program:&mut TsrTestContext<'_>,registry:&mut TsrTestRegistry)->Option<std::string::String>{let previous=TSR_TEST_BODY.with(|value|value.replace(true));let result=tsrust_testing_invoke(callback,program,registry);TSR_TEST_BODY.with(|value|value.set(previous));result}
